  final class SkeletonSlider extends View {
    Paint track=new Paint(Paint.ANTI_ALIAS_FLAG),fillPaint=new Paint(Paint.ANTI_ALIAS_FLAG),thumbPaint=new Paint(Paint.ANTI_ALIAS_FLAG); int max=100,progress=0; SliderListener listener;
    SkeletonSlider(){super(MainActivity.this);track.setColor(Color.rgb(52,59,66));fillPaint.setColor(ACCENT);thumbPaint.setColor(Color.WHITE);setFocusable(true);}
    void setMax(int m){max=Math.max(1,m);progress=Math.min(progress,max);invalidate();} int getProgress(){return progress;} void setProgress(int v){progress=Math.max(0,Math.min(max,v));invalidate();}
    void setOnValueListener(SliderListener l){listener=l;}
    @Override protected void onDraw(Canvas c){super.onDraw(c);float den=getResources().getDisplayMetrics().density,r=7.5f*den,h=4f*den,y=getHeight()/2f,x0=r,x1=Math.max(x0,getWidth()-r),f=max<=0?0f:(progress/(float)max),xp=x0+(x1-x0)*f;track.setStrokeWidth(h);track.setStrokeCap(Paint.Cap.ROUND);fillPaint.setStrokeWidth(h);fillPaint.setStrokeCap(Paint.Cap.ROUND);c.drawLine(x0,y,x1,y,track);c.drawLine(x0,y,xp,y,fillPaint);c.drawCircle(xp,y,r,thumbPaint);}
    int valueAt(float x){float den=getResources().getDisplayMetrics().density,r=7.5f*den,x0=r,x1=Math.max(x0+1,getWidth()-r),f=Math.max(0f,Math.min(1f,(x-x0)/(x1-x0)));return Math.round(f*max);}
    @Override public boolean onTouchEvent(android.view.MotionEvent e){if(!isEnabled())return false;int a=e.getActionMasked();if(a==android.view.MotionEvent.ACTION_DOWN||a==android.view.MotionEvent.ACTION_MOVE){setPressed(true);setProgress(valueAt(e.getX()));if(listener!=null)listener.changed(progress,true);return true;}if(a==android.view.MotionEvent.ACTION_UP||a==android.view.MotionEvent.ACTION_CANCEL){if(a==android.view.MotionEvent.ACTION_UP){setProgress(valueAt(e.getX()));if(listener!=null){listener.changed(progress,true);listener.stopped(progress);}}setPressed(false);return true;}return true;}
  }
