    SkeletonSelect(){super(MainActivity.this);setTextColor(TEXT);sizePx(this,14);weight(this,500);setGravity(Gravity.CENTER_VERTICAL);setIncludeFontPadding(false);setPadding(dp(10),0,dp(9),0);setBackgroundDrawable(bg(INPUT,9));setCompoundDrawables(null,null,icon("chevron-down",16,MUTED),null);setCompoundDrawablePadding(dp(6));setOnClickListener(v->openList());}
