  final class YoutubeDpad extends ViewGroup {
    Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG),line=new Paint(Paint.ANTI_ALIAS_FLAG); View up,left,right,down,ok;
    YoutubeDpad(){super(MainActivity.this);setWillNotDraw(false);line.setColor(Color.rgb(74,86,96));line.setAlpha(90);line.setStrokeWidth(dp(1));}
    void bind(View u,View l,View r,View d,View o){up=u;left=l;right=r;down=d;ok=o;addView(u);addView(l);addView(r);addView(d);addView(o);}
    @Override protected void onMeasure(int ws,int hs){int w=MeasureSpec.getSize(ws),h=MeasureSpec.getSize(hs),d=Math.max(1,Math.min(w,h));setMeasuredDimension(d,d);measureExact(up,(int)(d*.50f),(int)(d*.32f));measureExact(down,(int)(d*.50f),(int)(d*.32f));measureExact(left,(int)(d*.32f),(int)(d*.50f));measureExact(right,(int)(d*.32f),(int)(d*.50f));measureExact(ok,(int)(d*.38f),(int)(d*.38f));}
    void measureExact(View v,int w,int h){v.measure(MeasureSpec.makeMeasureSpec(Math.max(1,w),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(1,h),MeasureSpec.EXACTLY));}
    @Override protected void onLayout(boolean c,int l,int t,int r,int b){int d=getMeasuredWidth();layoutAt(up,(int)(d*.25f),0);layoutAt(down,(int)(d*.25f),d-down.getMeasuredHeight());layoutAt(left,0,(int)(d*.25f));layoutAt(right,d-right.getMeasuredWidth(),(int)(d*.25f));layoutAt(ok,(d-ok.getMeasuredWidth())/2,(d-ok.getMeasuredHeight())/2);}
    void layoutAt(View v,int x,int y){v.layout(x,y,x+v.getMeasuredWidth(),y+v.getMeasuredHeight());}
    @Override protected void onDraw(Canvas c){super.onDraw(c);int d=getWidth();float cx=d/2f,cy=d/2f,r=d/2f-1;paint.setShader(new RadialGradient(cx,cy,r,new int[]{Color.rgb(52,60,68),Color.rgb(36,43,50),Color.rgb(22,27,32)},new float[]{0f,.59f,1f},Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,paint);paint.setShader(null);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1));paint.setColor(Color.rgb(60,70,80));c.drawCircle(cx,cy,r,paint);paint.setStyle(Paint.Style.FILL);float k=(float)(r/Math.sqrt(2));c.drawLine(cx-k,cy-k,cx+k,cy+k,line);c.drawLine(cx+k,cy-k,cx-k,cy+k,line);}
  }
