    void measureExact(View v,int w,int h){v.measure(MeasureSpec.makeMeasureSpec(Math.max(1,w),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(1,h),MeasureSpec.EXACTLY));}
    @Override protected void onLayout(boolean c,int l,int t,int r,int b){int w=r-l,h=b-t;int total=sidePx+gapPx+dpadPx+gapPx+sidePx;int x=Math.max(0,(w-total)/2);int y=h-sidePx;back.layout(x,y,x+sidePx,y+sidePx);x+=sidePx+gapPx;dpad.layout(x,0,x+dpadPx,dpadPx);x+=dpadPx+gapPx;mute.layout(x,y,x+sidePx,y+sidePx);}
