  void buildApp(){
    root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);
    content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));
    screens[0]=buildHome();screens[1]=buildVideo();screens[2]=buildSk();screens[3]=buildDevices();for(View v:screens){content.addView(v,new FrameLayout.LayoutParams(-1,-1));v.setVisibility(View.GONE);}screens[0].setVisibility(View.VISIBLE);
    nav=row();nav.setBackgroundColor(Color.argb(250,10,13,16));nav.setPadding(dp(10),dp(6),dp(10),dp(6));
    for(int i=0;i<4;i++){final int n=i;Button b=iconTextButton(NAV_NAMES[i],NAV_ICONS[i],21,9,i==0?ACCENT:MUTED);b.setLetterSpacing(-.005f);b.setOnClickListener(v->showScreen(n));navButtons[i]=b;nav.addView(b,new LinearLayout.LayoutParams(0,dp(58),1));styleNav(i,i==0);}
    root.addView(nav,new LinearLayout.LayoutParams(-1,dp(70)));setContentView(root);
  }
