  void showScreen(int n){if(n==current&&screens[n].getVisibility()==View.VISIBLE)return;for(int i=0;i<4;i++){screens[i].setVisibility(i==n?View.VISIBLE:View.GONE);styleNav(i,i==n);}current=n;if(poller!=null)ui.removeCallbacks(poller);if(n==1)loadVideo();else if(n==2)pollSk();else if(n==3)pollDevices();else if(n==0)pollHome();schedulePoll(100);}
  void schedulePoll(long delay){if(!resumed)return;if(poller!=null)ui.removeCallbacks(poller);poller=()->{if(!resumed)return;if(current==0)pollHome();else if(current==2)pollSk();else if(current==3)pollDevices();schedulePoll(current==0?2500:current==2?10000:current==3?15000:30000);};ui.postDelayed(poller,delay);}

