  void discover(){net.execute(()->{String found=null;for(String s:SERVERS){try{HttpURLConnection c=(HttpURLConnection)new URL(s+"/health").openConnection();c.setConnectTimeout(1800);c.setReadTimeout(1800);if(c.getResponseCode()/100==2){found=s;c.disconnect();break;}c.disconnect();}catch(Exception e){}}final String f=found;ui.post(()->{server=f;for(TextView cv:connViews){boolean sk="СК".equals(String.valueOf(cv.getTag()));setText(cv,f==null?(sk?"Skeleton · Недоступно":"Home Edge · Недоступно"):(sk?"Skeleton · Підключено ●":"Home Edge · Підключено ●"));}if(f!=null){get("/api/ui/build?native="+VERSION,(j,e)->{});if(current==0)pollHome();else if(current==1)loadVideo();else if(current==2)pollSk();else if(current==3)pollDevices();}});});}
  JSONObject req(String method,String path,JSONObject body)throws Exception{if(server==null)throw new IOException("no server");HttpURLConnection c=(HttpURLConnection)new URL(server+path).openConnection();c.setConnectTimeout(3500);c.setReadTimeout(9000);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");OutputStream o=c.getOutputStream();o.write(body.toString().getBytes("UTF-8"));o.close();}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();StringBuilder sb=new StringBuilder();if(in!=null){BufferedReader r=new BufferedReader(new InputStreamReader(in,"UTF-8"));String line;while((line=r.readLine())!=null)sb.append(line);r.close();}c.disconnect();JSONObject j=sb.length()>0?new JSONObject(sb.toString()):new JSONObject();if(code>=400)throw new IOException(j.optString("error","HTTP "+code));return j;}
  void call(String method,String path,JSONObject body,JsonCb cb){if(server==null){discover();if(cb!=null)ui.post(()->cb.done(null,new IOException("Home Edge недоступний")));return;}net.execute(()->{try{JSONObject j=req(method,path,body);ui.post(()->{if(cb!=null)cb.done(j,null);});}catch(Exception e){ui.post(()->{if(cb!=null)cb.done(null,e);});}});}
  void get(String p,JsonCb c){call("GET",p,null,c);}void post(String p,JSONObject o,JsonCb c){call("POST",p,o,c);}void put(String p,JSONObject o,JsonCb c){call("PUT",p,o,c);}void del(String p,JsonCb c){call("DELETE",p,null,c);}

  void pollHome(){if(server==null)return;get("/api/mode",(m,e)->{if(e!=null)return;get("/api/player",(p,e2)->{if(e2!=null)return;get("/api/volume",(v,e3)->{if(e3==null)renderHome(m,p,v);});});});}
  void renderHome(JSONObject m,JSONObject p,JSONObject v){String key=m.toString()+"|"+p.optBoolean("pause")+"|"+p.optString("display-title")+"|"+(int)p.optDouble("time-pos")+"|"+(int)p.optDouble("duration")+"|"+v.optInt("master")+"|"+p.optString("poster_landscape")+"|"+p.optString("poster");if(key.equals(homeSnapshot))return;homeSnapshot=key;String mode=m.optString("mode",m.optString("tv_mode",""));String[] mm={"kiosk","mpv","tv","games"},mi={"youtube","cast-connected","television","gamepad-variant"};for(int i=0;i<4;i++){boolean a=mm[i].equals(mode);modeButtons[i].setTextColor(a?ACCENT:MUTED);weight(modeButtons[i],a?700:600);modeButtons[i].setCompoundDrawables(null,icon(mi[i],22,a?ACCENT:MUTED),null,null);}currentHomeMode=mode;boolean youtube=mode.equals("kiosk"),tv=mode.equals("tv");homePoster.ratio(youtube?16:2,youtube?9:3);homeYoutubePanel.setVisibility(youtube?View.VISIBLE:View.GONE);if(youtube)homeYoutubePanel.requestLayout();homeTvPanel.setVisibility(tv?View.VISIBLE:View.GONE);homeVisual.setVisibility(View.VISIBLE);homeTransport.setVisibility(youtube?View.GONE:View.VISIBLE);for(int i=0;i<4;i++)if(transportButtons[i]!=null)transportButtons[i].setVisibility(tv&&i<3?View.GONE:View.VISIBLE);homeTimeRow.setVisibility(tv?View.GONE:View.VISIBLE);homeSeek.setVisibility(tv?View.GONE:View.VISIBLE);if(tv)loadNativeTvChannels();boolean run=p.optBoolean("running");String title=run?opt(p,"display-title",opt(p,"media-title","Відео")):"Нічого не відтворюється";setText(homeTitle,title);String meta="";if(run&&p.has("season")){String se="S"+p.optString("season","");String ep=p.optString("episode","").replaceAll("[^0-9]","");if(ep.length()>0)se+=" · E"+ep;meta=se;}setText(homeMeta,meta);homeMeta.setTextColor(meta.length()>0?ACCENT:MUTED);homeMeta.setVisibility(meta.length()>0?View.VISIBLE:View.GONE);int d=(int)p.optDouble("duration",0),t=(int)p.optDouble("time-pos",0);homeSeek.setMax(Math.max(1,d));if(!homeSeek.isPressed())homeSeek.setProgress(Math.min(t,d));setText(homePos,fmt(t));setText(homeDur,fmt(d));int vol=v.optInt("master",0);if(!homeVolume.isPressed())homeVolume.setProgress(vol);setText(homeVol,vol+"%");String poster="kiosk".equals(currentHomeMode)?p.optString("poster_landscape",p.optString("poster","")):p.optString("poster",p.optString("poster_landscape",""));loadImage(homePoster,poster,"kiosk".equals(currentHomeMode));}
  void loadNativeTvChannels(){if(server==null)return;get("/api/tv/channels",(j,e)->{if(e!=null||!"tv".equals(currentHomeMode))return;JSONArray a=j.optJSONArray("channels");if(a==null)return;homeTvPanel.removeAllViews();int count=Math.min(7,a.length());for(int i=0;i<count;i++){JSONObject c=a.optJSONObject(i);if(c==null)continue;Button r=new Button(this);String name=c.optString("display_name",c.optString("name","Канал"));String prog=c.optString("programme_title","");r.setText(prog.length()>0?name+"\n"+prog:name);r.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);r.setTextColor(MUTED);sizePx(r,prog.length()>0?10:13);weight(r,650);r.setAllCaps(false);r.setBackgroundColor(Color.TRANSPARENT);final String id=c.optString("channel_id","");r.setOnClickListener(v->{JSONObject o=new JSONObject();try{o.put("channel_id",id);}catch(Exception x){}post("/api/tv/play",o,(x,er)->pollHome());});homeTvPanel.addView(r,new LinearLayout.LayoutParams(-1,0,1));}});}
  void remote(String a){JSONObject o=new JSONObject();try{o.put("action",a);o.put("phase","tap");}catch(Exception e){}post("/api/remote/control",o,(j,e)->{});}void toggleMute(){get("/api/volume",(j,e)->{if(e!=null)return;int n=j.optInt("master",0);int target=n==0?Math.max(1,j.optInt("last_nonzero",25)):0;JSONObject o=new JSONObject();try{o.put("level",target);}catch(Exception x){}post("/api/volume",o,(a,b)->pollHome());});}

