  void loadJob(String id){currentJob=id;get("/api/jobs/"+id,(j,e)->{if(e!=null){setText(videoMsg,"Home Edge недоступний");return;}videoJob=j;String st=j.optString("status","");if(st.equals("resolving")||st.equals("discovering")||st.equals("identified")||st.equals("cached_mapping_checked")||st.equals("searching_sources")||st.equals("candidates_found")){setText(videoMsg,"Шукаю перевірені джерела…");ui.postDelayed(()->{if(currentJob.equals(id))loadJob(id);},700);return;}videoSources=j.optJSONArray("sources");if(videoSources==null)videoSources=new JSONArray();renderVideoJob();});}
  void renderVideoJob(){JSONObject c=videoJob.optJSONObject("catalog");if(c==null)c=new JSONObject();setText(videoTitle,opt(c,"title",opt(videoJob,"title","Відео")));setText(videoMeta,(c.optString("content_type","")+" · "+c.optString("year","")).replaceAll("^ · | · $",""));setText(videoOverview,opt(c,"overview",""));String poster=c.optString("poster","");JSONObject sp=c.optJSONObject("season_posters");String prefSeason=videoSelection==null?"":videoSelection.optString("season","");if(sp!=null&&prefSeason.length()>0)poster=sp.optString(prefSeason,poster);loadImage(videoPoster,poster,false);updateSelectorsFromSources();loadExternalButtons();setText(videoMsg,videoSources.length()+" варіантів");}
  List<String> uniq(String key,String... filters){TreeSet<String> set=new TreeSet<String>(new Comparator<String>(){public int compare(String a,String b){int aa=num(a),bb=num(b);if(aa!=bb)return aa-bb;return a.compareTo(b);}});for(int i=0;i<videoSources.length();i++){JSONObject s=videoSources.optJSONObject(i);if(s==null||!match(s,filters))continue;String x=s.optString(key,"");if(x.length()>0)set.add(x);}return new ArrayList<String>(set);}int num(String x){Matcher m=Pattern.compile("(\\d+)").matcher(x==null?"":x);return m.find()?Integer.parseInt(m.group(1)):999999;}boolean match(JSONObject s,String... f){for(int i=0;i+1<f.length;i+=2)if(f[i+1]!=null&&f[i+1].length()>0&&!f[i+1].equals(s.optString(f[i],"")))return false;return true;}
  void updateSelectorsFromSources(){spinnerBusy=true;String ps=videoSelection==null?"":videoSelection.optString("season","");String pe=videoSelection==null?"":videoSelection.optString("episode","");String pv=videoSelection==null?"":videoSelection.optString("voice","");String pq="";String sid=videoSelection==null?"":videoSelection.optString("source_id","");for(int i=0;i<videoSources.length();i++){JSONObject s=videoSources.optJSONObject(i);if(s!=null&&sid.equals(s.optString("source_id"))){ps=s.optString("season",ps);pe=s.optString("episode",pe);pv=s.optString("translation",s.optString("group",pv));pq=s.optString("quality","");break;}}fillSelect(seasonSp,uniq("season"),ps);fillSelect(episodeSp,uniq("episode","season",sel(seasonSp)),pe);fillSelect(qualitySp,uniq("quality","season",sel(seasonSp),"episode",sel(episodeSp)),pq);fillSelect(voiceSp,voicesFor(sel(seasonSp),sel(episodeSp),sel(qualitySp)),pv);spinnerBusy=false;}
  List<String> voicesFor(String s,String e,String q){TreeSet<String> set=new TreeSet<String>();for(int i=0;i<videoSources.length();i++){JSONObject x=videoSources.optJSONObject(i);if(x==null||!match(x,"season",s,"episode",e,"quality",q))continue;String v=x.optString("translation",x.optString("group",""));if(v.length()>0)set.add(v);}return new ArrayList<String>(set);}
  void updateVideoSelectors(SkeletonSelect who){spinnerBusy=true;if(who==seasonSp){fillSelect(episodeSp,uniq("episode","season",sel(seasonSp)),"");fillSelect(qualitySp,uniq("quality","season",sel(seasonSp),"episode",sel(episodeSp)),"");fillSelect(voiceSp,voicesFor(sel(seasonSp),sel(episodeSp),sel(qualitySp)),"");}else if(who==episodeSp){fillSelect(qualitySp,uniq("quality","season",sel(seasonSp),"episode",sel(episodeSp)),"");fillSelect(voiceSp,voicesFor(sel(seasonSp),sel(episodeSp),sel(qualitySp)),"");}else if(who==qualitySp){fillSelect(voiceSp,voicesFor(sel(seasonSp),sel(episodeSp),sel(qualitySp)),"");}spinnerBusy=false;updateSeasonPoster();}
  void updateSeasonPoster(){JSONObject c=videoJob==null?null:videoJob.optJSONObject("catalog");if(c==null)return;String p=c.optString("poster","");JSONObject ss=c.optJSONObject("season_posters");if(ss!=null)p=ss.optString(sel(seasonSp),p);loadImage(videoPoster,p,false);}
  String sel(SkeletonSelect s){return s.value();}void fill(SkeletonSelect s,List<String> vals){s.setOptions(vals,"");}void fillSelect(SkeletonSelect s,List<String> vals,String wanted){s.setOptions(vals,wanted);}
  JSONObject selectedSource(){String se=sel(seasonSp),ep=sel(episodeSp),q=sel(qualitySp),v=sel(voiceSp);for(int i=0;i<videoSources.length();i++){JSONObject x=videoSources.optJSONObject(i);if(x==null)continue;String vv=x.optString("translation",x.optString("group",""));if(match(x,"season",se,"episode",ep,"quality",q)&&vv.equals(v))return x;}return null;}
  void applyVideo(){JSONObject s=selectedSource();if(s==null){toast("Оберіть варіант");return;}JSONObject o=new JSONObject();try{o.put("job_id",currentJob);o.put("source_id",s.optString("source_id"));o.put("season",s.optString("season"));o.put("episode",s.optString("episode"));o.put("voice",s.optString("translation",s.optString("group")));o.put("quality",s.optString("quality"));o.put("subtitles","off");}catch(Exception e){}post("/api/play",o,(j,e)->{if(e!=null){toast(e.getMessage());return;}toast("Застосовано");writeSelection(s);showScreen(0);});}
  void writeSelection(JSONObject s){JSONObject o=new JSONObject();try{o.put("job_id",currentJob);o.put("locked",true);o.put("url",videoJob.optString("page_url"));o.put("voice",s.optString("translation",s.optString("group")));o.put("season",s.optString("season"));o.put("episode",s.optString("episode"));o.put("source_id",s.optString("source_id"));o.put("title",opt(videoJob,"title",""));}catch(Exception e){}put("/api/video/selection",o,(j,e)->{});}
  void resetVideo(){del("/api/video/selection",(j,e)->{currentJob="";videoJob=null;videoSources=new JSONArray();videoSelection=new JSONObject();renderVideoEmpty();toast("Скинуто");});}
  void showHistoryDialog(){if(videoHistory==null||videoHistory.length()==0){toast("Історія порожня");return;}final ArrayList<JSONObject> all=new ArrayList<JSONObject>();for(int i=0;i<videoHistory.length();i++){JSONObject x=videoHistory.optJSONObject(i);if(x!=null)all.add(x);}LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);EditText search=new EditText(this);search.setHint("Знайти твір");search.setTextColor(TEXT);search.setHintTextColor(MUTED);box.addView(search,new LinearLayout.LayoutParams(-1,dp(52)));ListView list=new ListView(this);box.addView(list,new LinearLayout.LayoutParams(-1,dp(420)));final ArrayList<JSONObject> shown=new ArrayList<JSONObject>();final ArrayAdapter<String> ad=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,new ArrayList<String>());list.setAdapter(ad);final Runnable render=()->{String q=search.getText().toString().toLowerCase(Locale.getDefault());shown.clear();ad.clear();for(JSONObject x:all){String t=x.optString("title","")+" "+x.optString("year","")+" "+x.optString("overview","");if(q.length()==0||t.toLowerCase(Locale.getDefault()).contains(q)){shown.add(x);ad.add(x.optString("title")+(x.optInt("year",0)>0?" · "+x.optInt("year"):""));}}ad.notifyDataSetChanged();};render.run();AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Історія").setView(box).setNegativeButton("Закрити",null).create();list.setOnItemClickListener((p,v,pos,id)->{JSONObject x=shown.get(pos);dlg.dismiss();openHistory(x);});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render.run();}public void afterTextChanged(Editable e){}});dlg.show();}
  void openHistory(JSONObject x){String hid=x.optString("history_id","");JSONObject o=new JSONObject();try{o.put("history_id",hid);}catch(Exception e){}post("/api/video/history/open",o,(j,e)->{if(e!=null){toast("Не вдалося відкрити");return;}historyBtn.setText(x.optString("title","Історія"));videoSelection=j.optJSONObject("preferred");if(videoSelection==null)videoSelection=new JSONObject();currentJob=j.optString("job_id","");try{videoSelection.put("job_id",currentJob);}catch(Exception z){}loadJob(currentJob);});}
  void loadExternalButtons(){if(currentJob.length()==0){providerRow.setVisibility(View.GONE);return;}get("/api/video/external-links?job_id="+Uri.encode(currentJob),(j,e)->{if(e!=null)return;providerRow.setTag(j);boolean t=j.optString("trakt_url","").length()>0, m=j.optInt("tmdb_id",0)>0||j.optString("imdb_id","").length()>0;traktBtn.setVisibility(t?View.VISIBLE:View.GONE);moviebaseBtn.setVisibility(m?View.VISIBLE:View.GONE);providerRow.setVisibility(t||m?View.VISIBLE:View.GONE);setAppIcon(traktBtn,findPackage("Trakt",new String[]{"tv.trakt.trakt","com.trakt.android"}));setAppIcon(moviebaseBtn,findPackage("Moviebase",new String[]{"com.moviebase"}));});}
  String findPackage(String label,String[] candidates){PackageManager pm=getPackageManager();for(String p:candidates)try{pm.getApplicationInfo(p,0);return p;}catch(Exception e){}try{List<ApplicationInfo> apps=pm.getInstalledApplications(0);for(ApplicationInfo a:apps){String l=String.valueOf(pm.getApplicationLabel(a));if(l.toLowerCase(Locale.US).contains(label.toLowerCase(Locale.US)))return a.packageName;}}catch(Exception e){}return null;}
  void setAppIcon(ImageButton b,String pkg){if(pkg==null)return;try{b.setImageDrawable(getPackageManager().getApplicationIcon(pkg));}catch(Exception e){}}
  void openProvider(boolean trakt){Object tag=providerRow.getTag();if(!(tag instanceof JSONObject))return;JSONObject x=(JSONObject)tag;String pkg=findPackage(trakt?"Trakt":"Moviebase",trakt?new String[]{"tv.trakt.trakt","com.trakt.android"}:new String[]{"com.moviebase"});if(pkg==null){toast((trakt?"Trakt":"Moviebase")+" не встановлено");return;}ArrayList<String> uris=new ArrayList<String>();if(trakt){String u=x.optString("trakt_url","");if(u.length()>0){uris.add(u.replace("https://app.trakt.tv/","https://trakt.tv/"));uris.add(u);String path=u.replaceFirst("https?://[^/]+/","");uris.add("trakt://"+path);}}else{int id=x.optInt("tmdb_id",0);String typ=videoJob!=null&&videoJob.optJSONObject("catalog")!=null?videoJob.optJSONObject("catalog").optString("media_type","movie"):"movie";if(id>0){uris.add("moviebase://"+typ+"/"+id);uris.add("moviebase://details/"+typ+"/"+id);uris.add("moviebase://tmdb/"+id);uris.add("https://moviebase.app/"+typ+"/"+id);}}PackageManager pm=getPackageManager();for(String u:uris){try{Intent in=new Intent(Intent.ACTION_VIEW,Uri.parse(u));in.setPackage(pkg);if(in.resolveActivity(pm)!=null){startActivity(in);return;}}catch(Exception e){}}Intent launch=pm.getLaunchIntentForPackage(pkg);if(launch!=null){int id=x.optInt("tmdb_id",0);launch.putExtra("tmdb_id",id);launch.putExtra("id",id);launch.putExtra("media_type",videoJob!=null&&videoJob.optJSONObject("catalog")!=null?videoJob.optJSONObject("catalog").optString("media_type","movie"):"movie");startActivity(launch);toast("Застосунок відкрито; deep-link твору не зареєстрований");}else toast("Не вдалося відкрити застосунок");}

  void pollDevices(){if(server==null)return;get("/api/native/devices",(j,e)->{if(e!=null)return;JSONArray a=j.optJSONArray("items");if(a==null)return;String key=a.toString();if(key.equals(devicesSnapshot))return;devicesSnapshot=key;devicesList.removeAllViews();for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);if(d==null)continue;LinearLayout c=row();c.setGravity(Gravity.CENTER_VERTICAL);c.setBackgroundDrawable(bg(CARD,16));c.setPadding(dp(18),dp(14),dp(14),dp(14));ImageView iv=iconView("devices",34,TEXT);c.addView(iv,new LinearLayout.LayoutParams(dp(42),dp(44)));LinearLayout cp=new LinearLayout(this);cp.setOrientation(LinearLayout.VERTICAL);TextView n=tv(d.optString("name",d.optString("device_id")),17,TEXT);weight(n,650);cp.addView(n,new LinearLayout.LayoutParams(-1,dp(24)));Object on=d.opt("online");String st=on==JSONObject.NULL||on==null?"Стан не опитаний":(d.optBoolean("online")?"Онлайн":"Офлайн");TextView m=tv(st,11,MUTED);cp.addView(m,new LinearLayout.LayoutParams(-1,dp(20)));LinearLayout.LayoutParams cl=new LinearLayout.LayoutParams(0,dp(48),1);cl.setMargins(dp(13),0,0,0);c.addView(cp,cl);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(76));p.setMargins(0,dp(10),0,0);devicesList.addView(c,p);}});}


  void loadImage(ImageView view,String path,boolean landscape){if(path==null||path.length()==0){view.setImageDrawable(null);return;}String key=(String)view.getTag();if(path.equals(key))return;view.setTag(path);final String url=path.startsWith("http")?path:(server==null?"":server+path);if(url.length()==0)return;net.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(3000);c.setReadTimeout(5000);Bitmap bm=BitmapFactory.decodeStream(c.getInputStream());c.disconnect();ui.post(()->{if(path.equals(view.getTag())&&bm!=null)view.setImageBitmap(bm);});}catch(Exception e){}});}
  void handleIntent(Intent i){if(i==null||!Intent.ACTION_SEND.equals(i.getAction()))return;String text=i.getStringExtra(Intent.EXTRA_TEXT);if(text==null)return;Matcher m=Pattern.compile("https?://\\S+").matcher(text);if(!m.find())return;final String url=m.group();Runnable work=()->{JSONObject o=new JSONObject();try{o.put("url",url);}catch(Exception e){}post("/api/share",o,(j,e)->{if(e!=null){toast("Не вдалося відкрити посилання");return;}currentJob=j.optString("job_id","");videoSelection=new JSONObject();showScreen(1);loadJob(currentJob);});};if(server==null)ui.postDelayed(work,2200);else work.run();}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
